namespace sv_a6860b87fb07455293ab107cd54b9a02.Services;

/// <summary>
/// Scoped service that holds the current warehouse selection for a single circuit.
/// Each user gets their own instance, ensuring independent state.
/// </summary>
public sealed class WarehouseStateService : IDisposable
{
    private string _currentWarehouseId = "warehouse-a";

    public string CurrentWarehouseId
    {
        get => _currentWarehouseId;
        set
        {
            if (_currentWarehouseId == value) return;
            _currentWarehouseId = value;
            OnChanged?.Invoke();
        }
    }

    public event Action? OnChanged;

    public static IReadOnlyList<(string Id, string Name)> AvailableWarehouses { get; } =
    [
        ("warehouse-a", "Warehouse A"),
        ("warehouse-b", "Warehouse B"),
        ("warehouse-c", "Warehouse C"),
    ];

    public void Dispose() => OnChanged = null;
}

namespace sv_a6860b87fb07455293ab107cd54b9a02.Services;

/// <summary>
/// Scoped service that provides low-stock alert polling with notification events.
/// Polling is reference-counted: starts when the first subscriber activates,
/// stops when the last subscriber deactivates.
/// </summary>
public sealed class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private readonly Random _random = new();
    private CancellationTokenSource? _cts;
    private int _activeSubscribers;
    private int _lastCount;

    public int CurrentLowStockCount => _lastCount;

    /// <summary>
    /// Fired whenever polling detects new alert data. All subscribed components
    /// should call StateHasChanged when this fires.
    /// </summary>
    public event Action? OnAlertCountChanged;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChanged += HandleWarehouseChanged;
    }

    /// <summary>
    /// Simulates a database query for low-stock items.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Call when a component wants polling to be active. Polling starts on first call.
    /// </summary>
    public void StartPolling()
    {
        _activeSubscribers++;
        if (_activeSubscribers == 1)
        {
            _cts = new CancellationTokenSource();
            _ = PollLoopAsync(_cts.Token);
        }
    }

    /// <summary>
    /// Call when a component no longer needs polling. Polling stops when count reaches 0.
    /// </summary>
    public void StopPolling()
    {
        _activeSubscribers = Math.Max(0, _activeSubscribers - 1);
        if (_activeSubscribers == 0)
        {
            _cts?.Cancel();
            _cts?.Dispose();
            _cts = null;
        }
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                var count = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
                _lastCount = count;
                OnAlertCountChanged?.Invoke();

                await Task.Delay(TimeSpan.FromSeconds(10), ct);
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private void HandleWarehouseChanged()
    {
        // Restart polling immediately with new warehouse context
        if (_activeSubscribers > 0)
        {
            _cts?.Cancel();
            _cts?.Dispose();
            _cts = new CancellationTokenSource();
            _ = PollLoopAsync(_cts.Token);
        }
    }

    public void Dispose()
    {
        _warehouseState.OnChanged -= HandleWarehouseChanged;
        _cts?.Cancel();
        _cts?.Dispose();
        OnAlertCountChanged = null;
    }
}

