@rendermode InteractiveServer
@inject Services.InventoryAlertService AlertService
@inject Services.WarehouseStateService WarehouseState
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mt-4">
    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Current Warehouse</h5>
                <p class="card-text fs-4">
                    @GetWarehouseName(WarehouseState.CurrentWarehouseId)
                </p>
            </div>
        </div>
    </div>
    <div class="col-md-6">
        <div class="card border-warning">
            <div class="card-body">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="card-text fs-1 text-warning fw-bold">
                    @AlertService.CurrentLowStockCount
                </p>
                <p class="card-text text-muted">
                    Items below minimum levels (refreshes every 10s)
                </p>
            </div>
        </div>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChanged += HandleStateChanged;
        AlertService.OnAlertCountChanged += HandleStateChanged;
        AlertService.StartPolling();
    }

    private void HandleStateChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private static string GetWarehouseName(string id) =>
        Services.WarehouseStateService.AvailableWarehouses
            .FirstOrDefault(w => w.Id == id).Name ?? id;

    public void Dispose()
    {
        AlertService.StopPolling();
        WarehouseState.OnChanged -= HandleStateChanged;
        AlertService.OnAlertCountChanged -= HandleStateChanged;
    }
}

