        WarehouseState.OnChanged += HandleStateChanged;
        AlertService.OnAlertCountChanged += HandleStateChanged;
        AlertService.StartPolling();
    }

    private void HandleStateChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private static string GetWarehouseName(string id) =>
        Services.WarehouseStateService.AvailableWarehouses
            .FirstOrDefault(w => w.Id == id).Name ?? id;

    public void Dispose()
    {
        AlertService.StopPolling();
        WarehouseState.OnChanged -= HandleStateChanged;
        AlertService.OnAlertCountChanged -= HandleStateChanged;
    }
}

